#!/usr/bin/env python3
"""Print a drill-down HTML (built from assets/drill_template.html) to a PDF in which
every node, card and link jumps to its page.  usage: build_pdf.py in.html out.pdf
Runs the page's own view functions (overview, stageView, groupView, cardView, xView),
snapshots each into a <section>, rewrites #/... routes to #v-... anchors, prints with Chrome."""
import sys,os,subprocess,tempfile
src,out=sys.argv[1],sys.argv[2]
h=open(src).read()
k=h.index('function route(){')
CSS='\n@page{size:1560px 1100px;margin:24px}\nhtml,body{background:#fff}\nheader,#tip{display:none!important}\nmain{display:none}\n.pg{break-before:page;padding:0 8px}\n.pg:first-child{break-before:auto}\n.pg .crumbs{margin-bottom:2px}\n.pg h1{margin:4px 0 14px;font-size:20px}\n.pgmain{max-width:1500px}\n.toc{display:none!important}\n.xtab th{position:static!important}\n.canvas{overflow:visible!important}\n.canvas{break-inside:avoid;max-height:1000px}\n.canvas svg{max-width:100%;max-height:1000px;width:auto;height:auto;display:block;margin:0 auto}\n.scard,.nb a,.elist li,.sec{break-inside:avoid}\n.card{break-inside:auto}\n.scard{position:relative}\n.scard .cover{position:absolute;inset:0;z-index:0;border-radius:10px}\n.scard a:not(.cover){position:relative;z-index:1}\n.card{max-width:none!important}\nh2,h3,h4{break-after:avoid}\n'
TAIL='\nconst MAP=h=>{h=h.replace(/^#\\/?/,\'\');return \'v-\'+(h===\'\'?\'ov\':h.split(\'/\').map(x=>x.replace(/[^\\w-]/g,\'_\')).join(\'-\'))};\nconst book=document.createElement(\'div\');book.id=\'book\';document.body.appendChild(book);\nconst SVGNS=\'http://www.w3.org/2000/svg\';\nfunction snap(id,fn){\n  fn();\n  const sec=document.createElement(\'section\');sec.className=\'pg\';sec.id=id;\n  sec.innerHTML=\'<div class="crumbs">\'+$(\'crumbs\').innerHTML+\'</div><h1>\'+$(\'title\').innerHTML+\'</h1><div class="pgmain">\'+$(\'main\').innerHTML+\'</div>\';\n  sec.querySelectorAll(\'[data-go]\').forEach(e=>{\n    const href=\'#\'+MAP(e.dataset.go);\n    if(e instanceof SVGElement){const a=document.createElementNS(SVGNS,\'a\');a.setAttribute(\'href\',href);e.parentNode.insertBefore(a,e);a.appendChild(e);}\n    else{const a=document.createElement(\'a\');a.className=\'cover\';a.setAttribute(\'href\',href);e.insertBefore(a,e.firstChild);}\n    e.removeAttribute(\'data-go\');\n  });\n  sec.querySelectorAll(\'a[href^="#/"]\').forEach(a=>{a.setAttribute(\'href\',\'#\'+MAP(a.getAttribute(\'href\')));a.removeAttribute(\'onclick\')});\n  sec.querySelectorAll(\'a[href^="#"]\').forEach(a=>a.removeAttribute(\'onclick\'));\n  book.appendChild(sec);\n}\nsnap(\'v-ov\',overview);\nconst done=new Set();\nD.stages.forEach(s=>{\n  snap(MAP(\'#/s/\'+s.id),()=>stageView(s.id));\n  s.groups.forEach(g=>{\n    snap(MAP(\'#/g/\'+s.id+\'/\'+g.id),()=>groupView(s.id,g.id));\n    g.members.forEach(m=>{const b=baseOf(m);if(D.comps[b]&&!done.has(b)){done.add(b);snap(MAP(\'#/c/\'+b),()=>cardView(b));}});\n  });\n});\nObject.keys(D.comps).forEach(b=>{if(!done.has(b)){done.add(b);snap(MAP(\'#/c/\'+b),()=>cardView(b));}});\n(D.xc||[]).forEach(x=>snap(MAP(\'#/x/\'+x.id),()=>xView(x.id)));\nsnap(MAP(\'#/x/refs\'),()=>xView(\'refs\'));\ndocument.getElementById(\'main\').remove();\ndocument.title=\'ST Engineering drill-down\';\nwindow.__done=book.children.length;\n</script></body></html>\n'
book=h[:k].replace('</style>',CSS+'</style>',1)+TAIL
d=tempfile.mkdtemp(); p=os.path.join(d,'book.html'); open(p,'w').write(book)
chrome=os.environ.get('CHROME','/Applications/Google Chrome.app/Contents/MacOS/Google Chrome')
subprocess.run([chrome,'--headless=new','--disable-gpu','--no-pdf-header-footer','--print-to-pdf='+os.path.abspath(out),'--virtual-time-budget=120000','file://'+p],check=True,stderr=subprocess.DEVNULL)
print('wrote',out)
